void generate_terrain_profile(void) {
    /* Terrain Elevation Array: 0x00403100 (32 double elements) */
    double *terrain = (double *)0x00403100;
    for (int i = 0; i < 32; i++) {
        if (i < 11) {
            terrain[i] = 75.0 - ((double)i * 5.0); // West crater slope
        } else if (i <= 19) {
            terrain[i] = 10.0;                     // Mare Tranquillitatis Flat Pad
        } else {
            terrain[i] = 10.0 + ((double)(i - 19) * 6.25); // East crater ridge
        }
    }
}

void apply_thrust_vector(double param_1, double param_2) {
    if (*(int *)(0x00403200 + 0x40) != 0) return;
    if (param_1 < 0.0) param_1 = 0.0;
    if (param_1 > 1.0) param_1 = 1.0;
    double pitch = *(double *)(0x00403200 + 0x20) + (param_2 * 0.1);
    if (pitch > 1.57079632679) pitch = 1.57079632679;
    if (pitch < -1.57079632679) pitch = -1.57079632679;
    *(double *)(0x00403200 + 0x20) = pitch;
    double fuel = *(double *)(0x00403200 + 0x28);
    if (fuel <= 0.0) {
        *(double *)(0x00403200 + 0x28) = 0.0;
        *(double *)(0x00403200 + 0x30) = 0.0;
        *(int *)(0x00403200 + 0x44) = 999; // FUEL_EXHAUSTION
        *(double *)(0x00403200 + 0x38) = 4500.0;
        return;
    }
    *(double *)(0x00403200 + 0x30) = param_1;
    /* Throttle Curve Table: 0x00403000 */
    int step = (int)(param_1 * 10.0);
    if (step > 10) step = 10;
    double coeff = *(double *)(0x00403000 + (step * 8));
    double thrust = coeff * 45000.0;
    double burn = (thrust / 3049.86815) * 0.1;
    if (burn > fuel) {
        *(double *)(0x00403200 + 0x28) = 0.0;
        *(int *)(0x00403200 + 0x44) = 999;
    } else {
        *(double *)(0x00403200 + 0x28) = fuel - burn;
    }
    *(double *)(0x00403200 + 0x38) = 4500.0 + *(double *)(0x00403200 + 0x28);
}

double check_altitude_raycast(void) {
    double x = *(double *)(0x00403200 + 0x00);
    double y = *(double *)(0x00403200 + 0x08);
    double *terrain = (double *)0x00403100;
    double dx_segment = 32.25806451612903; // 1000.0 / 31.0
    if (x <= 0.0) return y - terrain[0];
    if (x >= 1000.0) return y - terrain[31];
    int seg = (int)(x / dx_segment);
    if (seg >= 31) seg = 30;
    double t = (x - ((double)seg * dx_segment)) / dx_segment;
    double y_terrain = ((1.0 - t) * terrain[seg]) + (t * terrain[seg + 1]);
    return y - y_terrain;
}

int evaluate_touchdown_dynamics(void) {
    double vy = *(double *)(0x00403200 + 0x18);
    double vx = *(double *)(0x00403200 + 0x10);
    double pitch = *(double *)(0x00403200 + 0x20);
    if (fabs(vy) > 3.0) {
        *(int *)(0x00403200 + 0x40) = -1; // CRASH_EXCESS_DESCENT_RATE
        return -1;
    }
    if (fabs(vx) > 1.5) {
        *(int *)(0x00403200 + 0x40) = -2; // CRASH_LATERAL_SHEAR
        return -2;
    }
    if (fabs(pitch) > 0.10) {
        *(int *)(0x00403200 + 0x40) = -3; // CRASH_EXCESS_TILT
        return -3;
    }
    double x = *(double *)(0x00403200 + 0x00);
    double dx_segment = 32.25806451612903;
    int seg = (int)(x / dx_segment);
    if (seg < 0) seg = 0;
    if (seg >= 31) seg = 30;
    double *terrain = (double *)0x00403100;
    double slope = fabs(terrain[seg + 1] - terrain[seg]) / dx_segment;
    if (slope > 0.08) {
        *(int *)(0x00403200 + 0x40) = -4; // CRASH_ROUGH_TERRAIN
        return -4;
    }
    *(int *)(0x00403200 + 0x40) = 1;      // TOUCHDOWN_SUCCESS
    *(double *)(0x00403200 + 0x10) = 0.0; // vx = 0
    *(double *)(0x00403200 + 0x18) = 0.0; // vy = 0
    *(double *)(0x00403200 + 0x30) = 0.0; // throttle = 0
    return 1;
}

void update_newtonian_physics(void) {
    if (*(int *)(0x00403200 + 0x40) != 0) return;
    double x = *(double *)(0x00403200 + 0x00);
    if (x < 0.0) x = 0.0;
    if (x > 999.0) x = 999.0;
    /* Mascon Gravity Anomaly: 0x00403080 */
    int sector = (int)(x / 62.5);
    if (sector >= 16) sector = 15;
    double local_g = 1.62 + *(double *)(0x00403080 + (sector * 8));
    /* Throttle Curve Table: 0x00403000 */
    double throttle = *(double *)(0x00403200 + 0x30);
    int step = (int)(throttle * 10.0);
    if (step > 10) step = 10;
    double thrust = *(double *)(0x00403000 + (step * 8)) * 45000.0;
    double pitch = *(double *)(0x00403200 + 0x20);
    double mass = *(double *)(0x00403200 + 0x38);
    double fx = thrust * sin(pitch);
    double fy = (thrust * cos(pitch)) - (mass * local_g);
    double ax = fx / mass;
    double ay = fy / mass;
    *(double *)(0x00403200 + 0x10) += ax * 0.1; // vx
    *(double *)(0x00403200 + 0x18) += ay * 0.1; // vy
    *(double *)(0x00403200 + 0x00) += *(double *)(0x00403200 + 0x10) * 0.1; // x
    *(double *)(0x00403200 + 0x08) += *(double *)(0x00403200 + 0x18) * 0.1; // y
    *(unsigned int *)(0x00403200 + 0x48) += 1; // tick_count++
    if (check_altitude_raycast() <= 0.0) {
        evaluate_touchdown_dynamics();
    }
}
